// === CONSTRUCCION VISUAL DEL DASHBOARD INTERACTIVO Y SELECTOR DE ESCENARIOS ===
// 1. Panel de Control de Escenarios (Fondo)
ShapeRectangle panelCtrl = new ShapeRectangle(
    SHAPE_DRAW_2D, true,
    20, 20, 0, 0,
    new java.awt.Color(200, 200, 200), new java.awt.Color(248, 249, 250),
    300, 210, 0, 1.0, LineStyle.SOLID
);
presentation.add(panelCtrl);

ShapeText titCtrl = new ShapeText(
    SHAPE_DRAW_2D, true,
    30, 42, 0, 0,
    new java.awt.Color(33, 37, 41), "CONFIGURACIÓN DE ESCENARIO",
    new Font("SansSerif", Font.BOLD, 13), ALIGNMENT_LEFT
);
presentation.add(titCtrl);

// Boton Escenario 0
ShapeButton btnEsc0 = new ShapeButton(
    this, true, 30, 55, 280, 32,
    new java.awt.Color(33, 37, 41), true,
    new Font("SansSerif", Font.BOLD, 11), "1. As-Is (40 hs, Pánico 1.5x)"
) {
    @Override
    public void action() {
        factorLatigoMain = 1.5;
        escalaTurnoMain = 4.2;
        domitecPlant.factorLatigo = 1.5;
        domitecPlant.escalaTurno = 4.2;
        lblEscenarioActual.setText("Escenario 0: As-Is (40h, Pánico)");
        lblEscenarioActual.setColor(new java.awt.Color(180, 40, 40));
        traceln(">>> [SELECCIÓN] Escenario 0 aplicado: Pánico=1.5 | 40 hs (escala=4.2)");
    }
};
presentation.add(btnEsc0);

// Boton Escenario 1
ShapeButton btnEsc1 = new ShapeButton(
    this, true, 30, 95, 280, 32,
    new java.awt.Color(33, 37, 41), true,
    new Font("SansSerif", Font.BOLD, 11), "2. Sin Pánico (40 hs, Racional 1.0x)"
) {
    @Override
    public void action() {
        factorLatigoMain = 1.0;
        escalaTurnoMain = 4.2;
        domitecPlant.factorLatigo = 1.0;
        domitecPlant.escalaTurno = 4.2;
        lblEscenarioActual.setText("Escenario 1: Sin Pánico (40h, Racional)");
        lblEscenarioActual.setColor(new java.awt.Color(220, 140, 0));
        traceln(">>> [SELECCIÓN] Escenario 1 aplicado: Racional=1.0 | 40 hs (escala=4.2)");
    }
};
presentation.add(btnEsc1);

